"use strict";const utils=require("../utils");module.exports=function(defaultFuncs,api,ctx){return async function setMessageReaction(reaction,messageID,callback){let resolveFunc=()=>{};let rejectFunc=()=>{};const returnPromise=new Promise((resolve,reject)=>{resolveFunc=resolve;rejectFunc=reject});if(!callback){callback=(err,data)=>{if(err)return rejectFunc(err);resolveFunc(data)}}else{const _userCb=callback;callback=(err,data)=>{if(err){_userCb(err);return rejectFunc(err)}_userCb(null,data);resolveFunc(data)}}try{if(reaction===undefined||reaction===null){throw new Error("Please enter a valid emoji.")}const action=reaction===""?"REMOVE_REACTION":"ADD_REACTION";const defData=await defaultFuncs.postFormData("https://www.facebook.com/webgraphql/mutation/",ctx.jar,{},{doc_id:"1491398900900362",variables:JSON.stringify({data:{client_mutation_id:ctx.clientMutationId++,actor_id:ctx.userID,action:action,message_id:messageID,reaction:reaction}}),dpr:1});const resData=await utils.parseAndCheckLogin(ctx,defaultFuncs)(defData);if(!resData){throw new Error("setMessageReaction returned empty object.")}callback(null,{success:true,action:action,messageID:messageID})}catch(err){utils.error("setMessageReaction",err);callback(err instanceof Error?err:new Error(String(err)))}return returnPromise}};
